import React, { useEffect, useState } from "react";
import RenderContent from "./RenderContent";
import { useNavigate } from "react-router-dom";
import Headerandnav from "./Headerandnav";

const HomePage = () => {
  const [articles, setArticles] = useState([]);
  const [officers, setOfficers] = useState([]);
  const [loadingArticles, setLoadingArticles] = useState(true);
  const [loadingOfficers, setLoadingOfficers] = useState(true);
  let nav = useNavigate();

  useEffect(() => {
    const fetchArticles = async () => {
      try {
        const response = await fetch("http://localhost:3001/article");
        const data = await response.json();
        setArticles(data);
      } catch (error) {
        console.error("Error fetching articles:", error);
      } finally {
        setLoadingArticles(false);
      }
    };

    const fetchOfficers = async () => {
      try {
        const response = await fetch("http://localhost:3001/officers");
        const data = await response.json();
        setOfficers(data);
      } catch (error) {
        console.error("Error fetching officers:", error);
      } finally {
        setLoadingOfficers(false);
      }
    };

    fetchArticles();
    fetchOfficers();
  }, []);

  if (loadingArticles || loadingOfficers) return <p>Loading...</p>;

  return (
    <>
      <div className="text-center">
        <Headerandnav />
      </div>
      <h2>Trending Articles</h2>
      <div className="d-flex">
        {articles.map((article) => (
          <div
            className="d-flex flex-wrap rounded-3 m-5"
            style={{ border: "1px solid black" }}
            key={article.id}
          >
            <div
              className="articleitem p-2 "
              onClick={() => {
                nav(`/articles/${article.id}`);
              }}
            >
              <div className="displaycont flexlimit">
                <h3>{article.title}</h3>
              </div>
              <p className="displaycont" style={{ paddingBottom: "1.5rem" }}>
                <b>Author:</b> {article.author}
              </p>
            </div>
            <div>
              <img src={article.displayimg} alt={article.title} />
            </div>
          </div>
        ))}
      </div>

      <h2>Our Officers</h2>
      <div className="d-flex flex-wrap">
        {officers.map((officer) => (
          <div
            key={officer.id}
            className="officer-card p-3 m-3 rounded-3"
            style={{ border: "1px solid #ccc", width: "200px" }}
          >
            {officer.photo && (
              <img
                src={`data:image/jpeg;base64,${btoa(String.fromCharCode(...new Uint8Array(officer.photo.data)))}`}
                alt={officer.fullName}
                style={{ width: "100%", height: "auto", marginBottom: "10px" }}
              />
            )}
            <h3>{officer.fullName}</h3>
            <p>Position: {officer.title}</p>
            <p>Bio: {officer.description}</p>
          </div>
        ))}
      </div>
    </>
  );
};

export default HomePage;
